#include <iostream>
#include <vector>
using namespace std;

void merge_parts(vector<long long>& values, vector<long long>& buffer,
                 int left, int middle, int right) {
    int first = left;
    int second = middle;
    int output = left;
    while (first < middle && second < right) {
        if (values[first] <= values[second]) {
            buffer[output++] = values[first++];
        } else {
            buffer[output++] = values[second++];
        }
    }
    while (first < middle) {
        buffer[output++] = values[first++];
    }
    while (second < right) {
        buffer[output++] = values[second++];
    }
    for (int index = left; index < right; ++index) {
        values[index] = buffer[index];
    }
}

void merge_sort(vector<long long>& values, vector<long long>& buffer,
                int left, int right) {
    if (right - left <= 1) {
        return;
    }
    int middle = left + (right - left) / 2;
    merge_sort(values, buffer, left, middle);
    merge_sort(values, buffer, middle, right);
    merge_parts(values, buffer, left, middle, right);
}

void sort_values(vector<long long>& values) {
    vector<long long> buffer(values.size());
    merge_sort(values, buffer, 0, static_cast<int>(values.size()));
}

int count_distinct(const vector<long long>& values) {
    int count = 0;
    for (int index = 0; index < static_cast<int>(values.size()); ++index) {
        if (index == 0 || values[index] != values[index - 1]) {
            ++count;
        }
    }
    return count;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int size;
    cin >> size;
    vector<long long> values(size);
    for (long long& value : values) {
        cin >> value;
    }
    sort_values(values);
    cout << count_distinct(values) << '\n';
    return 0;
}

